#include <stdio.h>
int main(void) {
    FILE *w = fopen("sz.bin", "wb");
    int x = 12345;
    for (int i = 0; i < 7; i++) fwrite(&x, sizeof(int), 1, w);
    fclose(w);
    FILE *r = fopen("sz.bin", "rb");
    fseek(r, 0L, SEEK_END);
    long sz = ftell(r);
    printf("file size = %ld bytes\n", sz);
    fseek(r, 0L, SEEK_SET);
    fclose(r);
    return 0;
}
